fn append(v: &Vec<u64>, elem: u64) -> Vec<u64> {
    // Clone the input vector (does not modify the original),
    // then push the new element onto the end.
    let mut result = v.clone();
    result.push(elem);
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_append_empty() {
        let v: Vec<u64> = Vec::new();
        let r = append(&v, 42);
        assert_eq!(r.len(), 1);
        assert_eq!(r[0], 42);
        // original vector is still empty
        assert!(v.is_empty());
    }

    #[test]
    fn test_append_non_empty() {
        let v = vec![1, 2, 3];
        let r = append(&v, 99);
        assert_eq!(r.len(), 4);
        assert_eq!(&r[0..3], &v[..]);
        assert_eq!(r[3], 99);
        // original vector is unmodified
        assert_eq!(v, vec![1, 2, 3]);
    }
}